// Puts text only the person reads, such as the printer form's, into the app's
// language. The files here that GUI-free tests build mark that text with L()
// or _L_PLURAL() for the catalog and translate it through this; left empty, as
// the tests leave it, it keeps the English. Text the model reads stays English
// and never goes through it.
struct Wording
{
    std::function<std::string(const char*)>                        text;
    std::function<std::string(const char*, const char*, unsigned)> plural;

    std::string operator()(const char* english) const { return text ? text(english) : std::string(english); }
    std::string operator()(const char* one, const char* many, unsigned n) const
    {
        return plural ? plural(one, many, n) : std::string(n == 1 ? one : many);
    }
};

class IPrinterBackend
{
public:
    virtual ~IPrinterBackend() = default;

    // The app's language for the printer form; see Wording.
    virtual Wording wording() const { return {}; }

    // Reads. The catalogue is every model a person can add from this panel,
    // in a stable order.
    : m_plater(plater), m_catalog(std::move(catalog)), m_profiles_directory(Slic3r::resources_dir() + "/profiles")
{
    m_models = m_catalog.panel_printers();
}

OrcaPrinterBackend::~OrcaPrinterBackend() = default;

Wording OrcaPrinterBackend::wording() const
{
    // The catalog is read-only once loaded, so the form's reads off the GUI
    // thread translate too, as libslic3r's slicing messages do.
    return {[](const char* english) { return _u8L(english); },
            [](const char* one, const char* many, unsigned n) { return std::string(_L_PLURAL(one, many, n).ToUTF8()); }};
}

